from __future__ import annotations

from decimal import Decimal

import pytest
from fastapi import HTTPException

from app.core.config import Settings
from app.libs.onboarding.service import OnboardingService
from app.models.onboarding import ClientOnboarding
from app.models.post_trade_allocation import ClientPortfolio
from app.models.users import AdminRole
from tests.libs.onboarding.conftest import (
    FakeIdentityService,
    FakeIdentityServiceWithSetPasswordLink,
    make_admin,
    make_model,
    make_start_req,
    run_to_reviewing,
)


@pytest.fixture
def svc(session, fake_storage):
    return OnboardingService(session)


@pytest.fixture
def rm(session):
    return make_admin(session, AdminRole.RM, name="Ricky RM")


@pytest.fixture
def compliance(session):
    return make_admin(session, AdminRole.COMPLIANCE, name="Cara Compliance")


@pytest.fixture
def model(session):
    return make_model(session)  # model_size=1_000_000 by default


def _dev_settings():
    from app.core.config import Settings

    return Settings(firebase_auth_disabled=True)


def _start(svc, model, rm, identity=None, **overrides):
    # NOTE: a shared `identity` must be passed in by callers that start() more
    # than one client in the same test -- a fresh FakeIdentityService's uid
    # counter restarts at 0 each time, so two independent instances mint the
    # SAME "fake-uid-1" and collide on users.firebase_uid's unique constraint.
    return svc.start(
        make_start_req(model, **overrides), caller_uid=rm.firebase_uid,
        identity=identity or FakeIdentityService(), settings=_dev_settings(),
    )


# --- Positive: exact boundary --------------------------------------------------------


def test_deposit_exactly_at_floor_succeeds_with_zero_cash_deposit(session, svc, model, rm):
    """units=5, model_size=1_000_000 -> amount_in_trade = 5_000_000. Floor = that
    exact amount -- must succeed (not 422), and seed no client_portfolios row
    (Unit 13: the table is frozen-but-readable, no longer written at intake)."""
    dto = _start(svc, model, rm, initial_cash_deposit=Decimal("5000000"))
    assert dto.units == 5.0
    assert session.get(ClientPortfolio, dto.user_id) is None


def test_deposit_comfortably_above_floor_succeeds_with_no_portfolio_row(session, svc, model, rm):
    dto = _start(svc, model, rm, initial_cash_deposit=Decimal("5250000"))
    assert dto.units == 5.0
    assert session.get(ClientPortfolio, dto.user_id) is None


# --- Negative: one cent under the floor ---------------------------------------------


def test_deposit_one_cent_under_floor_raises_422_and_creates_no_rows_at_all(session, svc, model, rm):
    with pytest.raises(HTTPException) as exc:
        _start(svc, model, rm, initial_cash_deposit=Decimal("4999999.99"))
    assert exc.value.status_code == 422

    assert session.query(ClientOnboarding).count() == 0
    assert session.query(ClientPortfolio).count() == 0


# --- Invariant: two clients onboarded in sequence never cross-contaminate ----------


def test_two_clients_onboarded_in_sequence_each_get_their_own_correctly_computed_units(
    session, svc, model, rm
):
    identity = FakeIdentityService()
    dto_a = _start(
        svc, model, rm, identity=identity, email="a@example.com",
        initial_cash_deposit=Decimal("5000000"),
    )
    dto_b = _start(
        svc, model, rm, identity=identity, email="b@example.com", units=Decimal("2"),
        initial_cash_deposit=Decimal("2500000"),
    )

    assert dto_a.units == 5.0
    assert dto_b.units == 2.0
    assert session.get(ClientPortfolio, dto_a.user_id) is None
    assert session.get(ClientPortfolio, dto_b.user_id) is None


# --- Invariant: renewal never seeds/touches client_portfolios ----------------------


def test_renewal_approve_never_creates_a_client_portfolios_row(
    session, svc, model, rm, compliance
):
    import io

    from app.libs.onboarding.compliance_doc_config import REQUIRED_DOCS
    from app.libs.onboarding.schemas import VerdictBatchReq, VerdictItem

    # Built locally rather than via conftest's run_full_approved_cycle: that
    # helper is pinned to the pre-019 `approve(id, compliance_uid=...)`
    # signature and its own docstring says it raises TypeError now that BE-20
    # added required identity/settings kwargs. 23 tests already fail that way;
    # this one must actually exercise the invariant, so it calls approve itself.
    def _approve(onboarding_id):
        return svc.approve(
            onboarding_id,
            compliance_uid=compliance.firebase_uid,
            identity=FakeIdentityServiceWithSetPasswordLink(),
            settings=Settings(firebase_auth_disabled=True, _env_file=None),
        )

    submitted = run_to_reviewing(svc, model, rm_uid=rm.firebase_uid)
    svc.verdict_batch(
        submitted.id,
        VerdictBatchReq(
            items=[VerdictItem(doc_type=spec.key, verdict="valid") for spec in REQUIRED_DOCS]
        ),
        reviewer_uid=compliance.firebase_uid,
    )
    approved = _approve(submitted.id)
    onboarding = session.get(ClientOnboarding, approved.id)
    doc = svc.repo.documents_for(onboarding.id)[0]

    svc.reopen_for_renewal(approved.user_id, due_docs=[doc], reason="periodic review due")
    svc.upload_document(
        onboarding.id, doc.doc_type, stream=io.BytesIO(b"renewed"), filename="r.pdf",
        content_type="application/pdf", caller_uid=rm.firebase_uid,
    )
    svc.submit(onboarding.id)
    pending = [
        spec.key
        for spec in REQUIRED_DOCS
        if svc.repo.get_document(onboarding.id, spec.key).status != "verified"
    ]
    svc.verdict_batch(
        onboarding.id,
        VerdictBatchReq(items=[VerdictItem(doc_type=k, verdict="valid") for k in pending]),
        reviewer_uid=compliance.firebase_uid,
    )
    _approve(onboarding.id)

    assert session.get(ClientPortfolio, approved.user_id) is None


